class BigWigToolsCliTest {
    @TempDir Path temporary;
    @Test void publicRootDispatchRunsBeforeAmbientProjectConfiguration(){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();assertEquals(0,JLinAlgCli.run(new String[]{"bigwig-tools","--help"},new PrintStream(out),new PrintStream(err)));assertTrue(out.toString(StandardCharsets.UTF_8).contains("--float32 exact|round"));assertEquals("",err.toString(StandardCharsets.UTF_8));}
    @Test void nativeHelpHasExplicitPrecisionAndDictionaryChoicesAndRecovery(){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();assertEquals(0,BigWigToolsCli.run(new String[]{"--help"},new PrintStream(out),new PrintStream(err)));String help=out.toString(StandardCharsets.UTF_8);for(String text:List.of("exact|round","used|all","SKIP3","FAIL2","--verify","no external runtime","literal-decimal"))assertTrue(help.contains(text),text);assertEquals("",err.toString(StandardCharsets.UTF_8));}
    @ParameterizedTest @ValueSource(strings={"zlib","none"})
    void fullPublicConversionPreservesGapsZerosRawInputsAndIndependentReaderValues(String compression)throws Exception {
        var f=files("# source\ntrack type=bedGraph name=literal\nchr2\t4\t6\t-0.0\nchr1 0 1 0.5\nchr1\t3\t10\t2\n","chr1\t100\nchr2\t100\nunused\t50\n");var result=run(args(f,"--compression",compression));assertEquals(0,result.exit,result.error);assertTrue(Files.exists(f.root.resolve("COMPLETED.json")));assertFalse(Files.exists(f.root.resolve("INCOMPLETE.json")));assertArrayEquals(Files.readAllBytes(f.signal),Files.readAllBytes(f.root.resolve("inputs/signal.bedGraph")));assertArrayEquals(Files.readAllBytes(f.sizes),Files.readAllBytes(f.root.resolve("inputs/reference.sizes")));var read=BigWigSignal.read(f.root.resolve("track.bw"),1000000,10000,100000);assertEquals(3,read.segments().size());assertEquals(2,read.dictionary().size());assertEquals(0,Float.floatToRawIntBits((float)read.segments().get(0).value())&Integer.MIN_VALUE);assertEquals(Integer.MIN_VALUE,Float.floatToRawIntBits((float)read.segments().get(2).value()));assertEquals(0,run(new String[]{"--verify",f.root.toString()}).exit);assertTrue(result.error.contains("OMITTED UNUSED CHROMOSOMES"));assertTrue(result.error.contains("SOURCE METADATA"));assertTrue(Files.readString(f.root.resolve("REFERENCE-LEDGER.tsv")).contains("unused\t50\t50\tfalse\tNA\t0"));
    }
    @Test void exactLiteralPolicyRejectsDecimalInformationLostBeforeFloat32()throws Exception {
        for(String token:List.of("0.1","0.50000000000000000000000000000000000001","1e-400")){var f=files("chr\t0\t1\t"+token+"\n","chr\t10\n");var result=run(args(f));assertEquals(2,result.exit);assertTrue(result.error.contains("Literal decimal loses precision"));assertFalse(Files.exists(f.root.resolve("track.bw")));assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));assertTrue(Files.readString(f.root.resolve("WARNINGS.md")).contains("FAIL2"));}
    }
    @Test void explicitRoundingRetainsDecimalDoubleFloatUnderflowAndSignedZeroDispositions()throws Exception {
        var f=files("chr\t0\t1\t0.1\nchr\t2\t3\t1e-400\nchr\t4\t5\t-1e-50\n","chr\t10\n");var result=run(args(f,"--float32","round"));assertEquals(0,result.exit,result.error);assertTrue(result.error.contains("PRECISION LOSS"));var audit=BigWigFiles.json(f.root.resolve("INPUT-AUDIT.json"),65536);assertEquals(3,NextflowFiles.integer(audit.get("literal_decimal_values_changed_in_float32"),0,100));assertEquals(1,NextflowFiles.integer(audit.get("literal_values_underflowed_in_float64"),0,100));assertEquals(1,NextflowFiles.integer(audit.get("float64_values_underflowed_in_float32"),0,100));String ledger=Files.readString(f.root.resolve("VALUE-LEDGER.tsv"));assertTrue(ledger.contains("\tFLOAT64\n"));assertTrue(ledger.contains("\t80000000\t"));assertTrue(ledger.contains("\tFLOAT32\n"));assertEquals(0,run(new String[]{"--verify",f.root.toString()}).exit);
    }
    @Test void sourceExactDecimalForStoredFloatIsAcceptedAndNoAliasOrNormalizationOccurs()throws Exception {
        var f=files("chr\t00\t01\t0.100000001490116119384765625\n","chr\t0010\n");var result=run(args(f));assertEquals(0,result.exit,result.error);assertTrue(Files.readString(f.root.resolve("VALUE-LEDGER.tsv")).contains("\t00\t01\t0.100000001490116119384765625\t"));assertTrue(Files.readString(f.root.resolve("REFERENCE-LEDGER.tsv")).contains("\t0010\t10\ttrue\t0\t1\n"));}
    @Test void strictConcatenatedGzipPreservesAllMembersAndOriginalCompressedBytes()throws Exception {
        byte[] a=gzip("chr\t0\t1\t0.5\n".getBytes(StandardCharsets.UTF_8)),b=gzip("chr\t2\t3\t2\n".getBytes(StandardCharsets.UTF_8));var f=files("","chr\t10\n");var joined=ByteBuffer.allocate(a.length+b.length).put(a).put(b).array();Files.write(f.signal,joined);var result=run(args(f,"--input-format","gzip"));assertEquals(0,result.exit,result.error);assertEquals(2,BigWigWorkflow.verify(f.root,()->{}).report().records());assertArrayEquals(joined,Files.readAllBytes(f.root.resolve("inputs/signal.bedGraph.gz")));
    }
    @Test void gzipOptionalHeadersMaximumExtraFieldAndHeaderCrcAreChecked()throws Exception {
        byte[] original=gzip("chr\t0\t1\t0.5\n".getBytes(StandardCharsets.UTF_8));var header=new ByteArrayOutputStream();header.write(new byte[]{31,(byte)139,8,30,0,0,0,0,0,(byte)255});header.write(255);header.write(255);header.write(new byte[65535]);header.write("literal name.bdg".getBytes(StandardCharsets.UTF_8));header.write(0);header.write("comment".getBytes(StandardCharsets.UTF_8));header.write(0);var crc=new java.util.zip.CRC32();crc.update(header.toByteArray());header.write((int)crc.getValue()&255);header.write((int)(crc.getValue()>>>8)&255);header.write(original,10,original.length-10);byte[] complete=header.toByteArray();var f=files("","chr\t10\n");Files.write(f.signal,complete);var result=run(args(f,"--input-format","gzip"));assertEquals(0,result.exit,result.error);assertEquals(0,run(new String[]{"--verify",f.root.toString()}).exit);complete[65550]^=1;var bad=files("","chr\t10\n");Files.write(bad.signal,complete);var failed=run(args(bad,"--input-format","gzip"));assertEquals(2,failed.exit);assertTrue(failed.error.contains("header CRC differs"));
    }
    @ParameterizedTest @ValueSource(strings={"crc","size","truncated","trailing","reserved","utf8"})
    void invalidGzipOrDecodedUtf8FailsWithoutAdmittingAPartialTrack(String mutation)throws Exception {
        byte[] valid=gzip("chr\t0\t1\t1\n".getBytes(StandardCharsets.UTF_8)),bad=valid.clone();switch(mutation){case "crc"->bad[bad.length-8]^=1;case "size"->bad[bad.length-4]^=1;case "truncated"->bad=java.util.Arrays.copyOf(bad,bad.length-1);case "trailing"->bad=ByteBuffer.allocate(bad.length+3).put(bad).put(new byte[]{1,2,3}).array();case "reserved"->bad[3]=(byte)128;case "utf8"->bad=gzip(new byte[]{(byte)0xff,10});default->throw new AssertionError(mutation);}var f=files("","chr\t10\n");Files.write(f.signal,bad);var result=run(args(f,"--input-format","gzip"));assertEquals(2,result.exit,result.error);assertFalse(Files.exists(f.root.resolve("track.bw")));assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));assertTrue(Files.exists(f.root.resolve("FAILURE.json")));
    }
    @ParameterizedTest @ValueSource(strings={"records","line","decoded","input","workspace","output"})
    void declaredCapacityFailuresRetainNamedStageAndNoOverallCompletion(String capacity)throws Exception {
        var f=files("chr\t0\t1\t0.5\nchr\t2\t3\t1\n","chr\t10\n");String option,value;switch(capacity){case "records"->{option="--records";value="1";}case "line"->{Files.writeString(f.signal,"chr\t0\t1\t"+"1".repeat(40)+"\n");option="--line-chars";value="32";}case "decoded"->{Files.write(f.signal,gzip(Files.readAllBytes(f.signal)));option="--decoded-bytes";value="12";}case "input"->{option="--input-bytes";value="8";}case "workspace"->{option="--workspace-bytes";value="16777473";}case "output"->{option="--output-bytes";value="256";}default->throw new AssertionError(capacity);}var values=capacity.equals("decoded")?args(f,option,value,"--input-format","gzip"):capacity.equals("workspace")?args(f,option,value,"--output-bytes","256"):args(f,option,value);var result=run(values);assertEquals(2,result.exit,result.error);assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));assertTrue(Files.exists(f.root.resolve("FAILURE.json")));assertTrue(Files.readString(f.root.resolve("WARNINGS.md")).contains("NO RESULT ADMITTED"));if(capacity.equals("output"))assertTrue(Files.exists(f.root.resolve("track.bw")));
    }
    @ParameterizedTest @ValueSource(strings={"overlap","unsorted","reappears","unknown","bounds","zero-width","duplicate-sizes","late-header","extra-field","nan","float-overflow"})
    void invalidCoordinateReferenceAndNumericalPopulationsAreNotSilentlyRepaired(String failure)throws Exception {
        String signal="chr\t0\t1\t1\n",sizes="chr\t10\nother\t10\n";switch(failure){case "overlap"->signal="chr\t0\t3\t1\nchr\t2\t4\t1\n";case "unsorted"->signal="chr\t2\t3\t1\nchr\t0\t1\t1\n";case "reappears"->signal="chr\t0\t1\t1\nother\t0\t1\t1\nchr\t2\t3\t1\n";case "unknown"->signal="missing\t0\t1\t1\n";case "bounds"->signal="chr\t0\t11\t1\n";case "zero-width"->signal="chr\t0\t0\t1\n";case "duplicate-sizes"->sizes="chr\t10\nchr\t10\n";case "late-header"->signal+="track type=bedGraph\n";case "extra-field"->signal="chr\t0\t1\t1\textra\n";case "nan"->signal="chr\t0\t1\tNaN\n";case "float-overflow"->signal="chr\t0\t1\t1e40\n";default->throw new AssertionError(failure);}var f=files(signal,sizes);var result=run(args(f));assertEquals(2,result.exit,result.error);assertFalse(Files.exists(f.root.resolve("track.bw")));assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));
    }
    @Test void emptyAllReferenceAndUnsigned32TracksHaveProminentSpecificCompatibilityWarnings()throws Exception {
        var empty=files("# no measurements\n","chr\t10\n");var result=run(args(empty,"--dictionary","all"));assertEquals(0,result.exit,result.error);assertTrue(result.error.contains("EMPTY TRACK"));assertEquals(0,BigWigWorkflow.verify(empty.root,()->{}).report().coveredBases());var wide=files("huge\t2147483648\t2147483651\t2\n","huge\t4294967295\n");var large=run(args(wide));assertEquals(0,large.exit,large.error);assertTrue(large.error.contains("UNSIGNED32 COMPATIBILITY"));assertEquals(3,BigWigWorkflow.verify(wide.root,()->{}).report().coveredBases());
    }
    @Test void copiedBundleVerifiesWithUnreachableCrossPlatformProducerPaths()throws Exception {
        var f=files("chr\t0\t1\t1\n","chr\t10\n");assertEquals(0,run(args(f)).exit);Files.delete(f.signal);Files.delete(f.sizes);Path copy=temporary.resolve("copied Unicode α");Files.move(f.root,copy);var request=map(copy.resolve("request.json"));request.put("producer_input","/unavailable/original/signal with spaces α.bedGraph");request.put("producer_sizes","Z:\\unavailable\\reference.sizes");replace(copy.resolve("request.json"),request);reseal(copy);assertEquals(0,run(new String[]{"--verify",copy.toString()}).exit);
    }
    @ParameterizedTest @ValueSource(strings={"value-ledger","reference-ledger","input-audit","output-audit","track","warnings","unknown-empty-directory"})
    void semanticTamperingStillFailsAfterManifestHashesAreRecomputed(String tamper)throws Exception {
        var f=files("chr\t0\t1\t0.5\n","chr\t10\nunused\t10\n");assertEquals(0,run(args(f)).exit);String expected;switch(tamper){case "value-ledger"->{Path p=f.root.resolve("VALUE-LEDGER.tsv");Files.writeString(p,Files.readString(p).replace("3f000000","3f800000"));expected="ledger differs";}case "reference-ledger"->{Path p=f.root.resolve("REFERENCE-LEDGER.tsv");Files.writeString(p,Files.readString(p).replace("false\tNA","true\t0"));expected="ledger differs";}case "input-audit"->{var doc=map(f.root.resolve("INPUT-AUDIT.json"));doc.put("source_records_filtered",1);replace(f.root.resolve("INPUT-AUDIT.json"),doc);expected="precision audit differs";}case "output-audit"->{var doc=map(f.root.resolve("OUTPUT-AUDIT.json"));doc.put("complete_raw_intervals",2);replace(f.root.resolve("OUTPUT-AUDIT.json"),doc);expected="output/ledger audit differs";}case "track"->{Path p=f.root.resolve("track.bw");byte[] bytes=Files.readAllBytes(p);bytes[bytes.length-1]^=1;Files.write(p,bytes);expected="index/structure differs";}case "warnings"->{Files.writeString(f.root.resolve("WARNINGS.md"),"No warnings.\n");expected="warnings or recovery";}case "unknown-empty-directory"->{Files.createDirectory(f.root.resolve("unknown"));expected="family has missing/unknown";}default->throw new AssertionError(tamper);}reseal(f.root);IOException error=assertThrows(IOException.class,()->BigWigWorkflow.verify(f.root,()->{}));assertTrue(error.getMessage().contains(expected),error.toString());
    }
    @Test void incompleteFailureOrMissingOverallMarkerCannotBeAdmitted()throws Exception {
        for(String marker:List.of("INCOMPLETE.json","FAILURE.json","MISSING")){var f=files("chr\t0\t1\t1\n","chr\t10\n");assertEquals(0,run(args(f)).exit);if(marker.equals("MISSING"))Files.delete(f.root.resolve("COMPLETED.json"));else Files.writeString(f.root.resolve(marker),"{}\n");assertEquals(2,run(new String[]{"--verify",f.root.toString()}).exit);}
    }
    @Test void cancellationAndErrorsBeforeFinalCommitRevokeEveryOverallMarker()throws Exception {
        for(boolean error:List.of(false,true)){var f=files("chr\t0\t1\t1\n","chr\t10\n");var spec=BigWigRequest.cli(options(args(f)));if(error)assertThrows(AssertionError.class,()->BigWigWorkflow.start(spec,f.root,()->{if(Files.exists(f.root.resolve("COMPLETED.json")))throw new AssertionError("controlled finalization error");}));else assertThrows(CancellationException.class,()->BigWigWorkflow.start(spec,f.root,()->{if(Files.exists(f.root.resolve("COMPLETED.json")))throw new CancellationException("controlled finalization cancellation");}));assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));assertTrue(Files.exists(f.root.resolve("UNADMITTED-COMPLETED.json")));assertTrue(Files.exists(f.root.resolve("FAILURE.json")));assertTrue(Files.exists(f.root.resolve("INCOMPLETE.json")));assertEquals(2,run(new String[]{"--verify",f.root.toString()}).exit);}
    }
    @Test void unknownDuplicateAndMissingOptionsOrExistingOutputsNeverOverwriteWork()throws Exception {
        var f=files("chr\t0\t1\t1\n","chr\t10\n");assertEquals(2,run(new String[]{"--unknown","x"}).exit);var duplicate=new ArrayList<>(List.of(args(f)));duplicate.addAll(List.of("--input",f.signal.toString()));assertEquals(2,run(duplicate.toArray(String[]::new)).exit);assertFalse(Files.exists(f.root));Files.createDirectory(f.root);Files.writeString(f.root.resolve("keep.txt"),"keep");assertEquals(2,run(args(f)).exit);assertEquals("keep",Files.readString(f.root.resolve("keep.txt")));assertFalse(Files.exists(f.root.resolve("FAILURE.json")));
    }
    @Test void impossibleWorkspaceReservationFailsBeforeCreatingAnAttempt()throws Exception {var f=files("chr\t0\t1\t1\n","chr\t10\n");var result=run(args(f,"--output-bytes","256","--workspace-bytes","1024"));assertEquals(2,result.exit);assertTrue(result.error.contains("16MiB final metadata reserve"));assertFalse(Files.exists(f.root));}
    @Test void coordinateBearingTrackBrowserRowsCannotDisappearAsDisplayMetadata()throws Exception {for(String row:List.of("track\t0\t1\t1\textra\n","track\t0\t1\n","browser\t0\t1\t1\textra\n")){var f=files(row,"chr\t10\n");var result=run(args(f,"--dictionary","all"));assertEquals(2,result.exit,result.error);assertFalse(Files.exists(f.root.resolve("COMPLETED.json")));assertFalse(Files.exists(f.root.resolve("track.bw")));}var valid=files("track\t0\t1\t1\n","track\t10\n");var accepted=run(args(valid));assertEquals(0,accepted.exit,accepted.error);assertEquals(1,BigWigWorkflow.verify(valid.root,()->{}).report().records());}
    private record Fixture(Path signal,Path sizes,Path root) { }
    private Fixture files(String signal,String sizes)throws IOException {Path parent=Files.createTempDirectory(temporary,"source-");Path data=parent.resolve("signal α with spaces.bdg"),reference=parent.resolve("reference α.sizes");Files.writeString(data,signal,StandardCharsets.UTF_8);Files.writeString(reference,sizes,StandardCharsets.UTF_8);return new Fixture(data,reference,parent.resolve("result"));}
    private static String[] args(Fixture f,String... changed){var values=new LinkedHashMap<String,String>();values.put("--input",f.signal.toString());values.put("--sizes",f.sizes.toString());values.put("--genome-build","synthetic-test-reference");values.put("--units","supplied unnormalized values");values.put("--float32","exact");values.put("--dictionary","used");values.put("--compression","zlib");values.put("--out",f.root.toString());for(int i=0;i<changed.length;i+=2)values.put(changed[i],changed[i+1]);var result=new ArrayList<String>();values.forEach((k,v)->{result.add(k);result.add(v);});return result.toArray(String[]::new);}
    private static Map<String,String> options(String[] args){var result=new LinkedHashMap<String,String>();for(int i=0;i<args.length;i+=2)result.put(args[i],args[i+1]);return result;}
    private record Run(int exit,String output,String error) { }
    private static Run run(String[] args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int status=BigWigToolsCli.run(args,new PrintStream(out),new PrintStream(err));return new Run(status,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private static byte[] gzip(byte[] raw)throws IOException {var out=new ByteArrayOutputStream();try(var gz=new GZIPOutputStream(out)){gz.write(raw);}return out.toByteArray();}
    private static Map<String,Object> map(Path file)throws IOException {var result=new LinkedHashMap<String,Object>();for(var e:BigWigFiles.json(file,2097152).entrySet())result.put(NextflowFiles.text(e.getKey()),e.getValue());return result;}
    private static void replace(Path file,Object value)throws IOException {Files.writeString(file,RsemJson.json(value)+"\n",StandardCharsets.UTF_8);}
    private static void reseal(Path root)throws IOException {var spec=BigWigRequest.captured(BigWigFiles.json(root.resolve("request.json"),2097152));var files=new java.util.TreeMap<>(BigWigFiles.inventory(root,spec,()->{}));for(String name:Set.of("manifest.json","COMPLETED.json"))assertNotNull(files.remove(name));var manifest=map(root.resolve("manifest.json"));manifest.put("files",files);replace(root.resolve("manifest.json"),manifest);var completion=map(root.resolve("COMPLETED.json"));completion.put("manifest",BigWigFiles.pin(NextflowFiles.pin(root.resolve("manifest.json"),2097152,()->{})));replace(root.resolve("COMPLETED.json"),completion);}
}
